// Turns canvas strokes into the point sequence the encoder expects.
//
// Straight port of ml/src/features.py — the two must stay in step, because a
// model trained on one representation and fed another produces confident
// nonsense rather than an error. The parity test in
// test/ink_recognizer_parity_test.dart pins the numbers against reference
// vectors generated by the Python side.
//
// Three steps:
//
//  1. Scale normalisation: the ink is centred on the origin and its bounding-box
//     *height* scaled to 1. Height, not width, because height is what carries
//     meaning in maths — the size ratio between a base and its exponent is what
//     separates `x^2` from `x2`. Width is only "how long is the formula" and must
//     not change the scale, or a long expression would shrink its own symbols
//     into noise.
//
//  2. Arc-length resampling: a point every [step] units of travel along each
//     stroke. Raw sampling density follows writing speed and the digitizer's
//     rate, so the same shape drawn slowly arrives with three times the points.
//     Resampling removes that. Timestamps and pressure are dropped: after
//     resampling they no longer describe the emitted points, and the model was
//     trained without them.
//
//  3. Six channels per point: x, y (absolute, the structural signal — what is
//     raised, what sits under a fraction bar), dx, dy (offset from the previous
//     point of the same stroke, zero at a stroke start, the translation-invariant
//     shape signal), isStart, isEnd (pen just went down / about to lift).
//
// Coordinates stay in the canvas frame with y growing downward, matching both
// the training data's digitizer convention and StrokePoint, so no flip is needed.

import 'dart:math' as math;
import 'dart:typed_data';

import 'package:abelnotes/shared/models/ncnote_format.dart';

/// x, y, dx, dy, isStart, isEnd
const int kFeatureCount = 6;

/// Default arc-length step, in units of normalised ink height. Must match
/// `--step` used to build the training cache.
const double kDefaultStep = 0.05;

class InkFeatures {
  InkFeatures(this.values, this.pointCount);

  /// Row-major [pointCount, kFeatureCount].
  final Float32List values;
  final int pointCount;

  bool get isEmpty => pointCount == 0;
}

/// Extracts features from [strokes], optionally capping the point count.
///
/// Returns an empty result when there is nothing usable. [maxPoints] truncates
/// from the end; leave it null unless there is a hard budget, since truncation
/// silently drops the tail of the expression.
InkFeatures extractFeatures(
  List<StrokeData> strokes, {
  double step = kDefaultStep,
  int? maxPoints,
}) {
  final normalised = _normalise(strokes);
  if (normalised.isEmpty) return InkFeatures(Float32List(0), 0);

  final resampled = <Float32List>[];
  var total = 0;
  for (final stroke in normalised) {
    final pts = _resample(stroke, step);
    if (pts.length < 2) {
      // A dot is a legitimate symbol (a decimal point, an accent), so a
      // single-point stroke is kept rather than discarded.
      if (pts.isEmpty) continue;
    }
    resampled.add(pts);
    total += pts.length >> 1;
  }
  if (total == 0) return InkFeatures(Float32List(0), 0);

  final count = maxPoints != null && total > maxPoints ? maxPoints : total;
  final out = Float32List(count * kFeatureCount);
  var row = 0;
  for (final pts in resampled) {
    final n = pts.length >> 1;
    for (var i = 0; i < n && row < count; i++, row++) {
      final base = row * kFeatureCount;
      final x = pts[i * 2];
      final y = pts[i * 2 + 1];
      out[base] = x;
      out[base + 1] = y;
      if (i > 0) {
        out[base + 2] = x - pts[(i - 1) * 2];
        out[base + 3] = y - pts[(i - 1) * 2 + 1];
      }
      if (i == 0) out[base + 4] = 1.0;
      if (i == n - 1) out[base + 5] = 1.0;
    }
    if (row >= count) break;
  }
  return InkFeatures(out, count);
}

/// Centres the ink and scales its bounding-box height to 1.
///
/// Each returned list is a flat [x0, y0, x1, y1, ...] for one stroke. A single
/// dot or a perfectly horizontal dash has a height of ~0, which would send the
/// scale to infinity, so the divisor is floored against a fraction of the width
/// and against an absolute epsilon.
List<Float32List> _normalise(List<StrokeData> strokes) {
  var minX = double.infinity, minY = double.infinity;
  var maxX = double.negativeInfinity, maxY = double.negativeInfinity;
  var any = false;
  for (final stroke in strokes) {
    for (final p in stroke.points) {
      any = true;
      if (p.x < minX) minX = p.x;
      if (p.x > maxX) maxX = p.x;
      if (p.y < minY) minY = p.y;
      if (p.y > maxY) maxY = p.y;
    }
  }
  if (!any) return const [];

  final width = maxX - minX;
  final height = maxY - minY;
  final divisor = math.max(math.max(height, width * 0.05), 1e-6);
  final scale = 1.0 / divisor;
  final cx = (minX + maxX) / 2.0;
  final cy = (minY + maxY) / 2.0;

  final out = <Float32List>[];
  for (final stroke in strokes) {
    if (stroke.points.isEmpty) continue;
    final flat = Float32List(stroke.points.length * 2);
    for (var i = 0; i < stroke.points.length; i++) {
      flat[i * 2] = (stroke.points[i].x - cx) * scale;
      flat[i * 2 + 1] = (stroke.points[i].y - cy) * scale;
    }
    out.add(flat);
  }
  return out;
}

/// Re-emits a stroke with points spaced [step] apart along its arc length.
///
/// Repeated coordinates are dropped first: they are zero-length segments, which
/// would put a 0/0 into the interpolation. Always keeps the first and last point,
/// so a stroke shorter than one step survives as its two endpoints.
Float32List _resample(Float32List flat, double step) {
  final n = flat.length >> 1;
  if (n == 0) return Float32List(0);

  final xs = <double>[flat[0]];
  final ys = <double>[flat[1]];
  for (var i = 1; i < n; i++) {
    final x = flat[i * 2];
    final y = flat[i * 2 + 1];
    if (x != xs.last || y != ys.last) {
      xs.add(x);
      ys.add(y);
    }
  }
  if (xs.length < 2) {
    return Float32List.fromList([xs[0], ys[0]]);
  }

  final arc = Float64List(xs.length);
  for (var i = 1; i < xs.length; i++) {
    final dx = xs[i] - xs[i - 1];
    final dy = ys[i] - ys[i - 1];
    arc[i] = arc[i - 1] + math.sqrt(dx * dx + dy * dy);
  }
  final total = arc[xs.length - 1];
  final nOut = math.max((total / step).floor() + 1, 2);

  final out = Float32List(nOut * 2);
  var seg = 0;
  for (var i = 0; i < nOut; i++) {
    // linspace(0, total, nOut) — computed from the index rather than
    // accumulated, so the last target is exactly `total`.
    final target = nOut == 1 ? 0.0 : total * i / (nOut - 1);
    while (seg < xs.length - 2 && arc[seg + 1] < target) {
      seg++;
    }
    final spanStart = arc[seg];
    final span = arc[seg + 1] - spanStart;
    final t = span <= 0 ? 0.0 : (target - spanStart) / span;
    out[i * 2] = xs[seg] + (xs[seg + 1] - xs[seg]) * t;
    out[i * 2 + 1] = ys[seg] + (ys[seg + 1] - ys[seg]) * t;
  }
  return out;
}
